import { describe, expect, it } from "vitest";
import { readTraceIdAlias, resolveReplayItemIdentity, } from "./replayItemIdentity.js";
describe("resolveReplayItemIdentity", () => {
    it("modern lineage (camelCase): originalTraceId is the persist key, traceId is the replay slot", () => {
        // Real current-SDK progress shape: traceId is null until the run completes.
        expect(resolveReplayItemIdentity({
            originalTraceId: "orig-1",
            traceId: null,
        })).toEqual({
            originalTraceId: "orig-1",
            traceId: null,
            replayTraceId: null,
            persistKey: "orig-1",
        });
    });
    it("modern lineage (snake_case): reads original_trace_id / trace_id", () => {
        expect(resolveReplayItemIdentity({
            original_trace_id: "orig-1",
            trace_id: "server-replay-1",
        })).toEqual({
            originalTraceId: "orig-1",
            traceId: "server-replay-1",
            replayTraceId: null,
            persistKey: "orig-1",
        });
    });
    it("deprecated sourceTraceId alias still resolves to originalTraceId", () => {
        expect(resolveReplayItemIdentity({
            sourceTraceId: "orig-1",
            traceId: null,
        })).toMatchObject({
            originalTraceId: "orig-1",
            persistKey: "orig-1",
        });
        expect(resolveReplayItemIdentity({ source_trace_id: "orig-1" })).toMatchObject({ originalTraceId: "orig-1", persistKey: "orig-1" });
    });
    it("canonical originalTraceId wins over the deprecated sourceTraceId alias", () => {
        expect(resolveReplayItemIdentity({
            originalTraceId: "canonical",
            sourceTraceId: "deprecated",
        })).toMatchObject({ originalTraceId: "canonical", persistKey: "canonical" });
    });
    it("oldest SDK (no lineage): the server replay traceId is the direct persist key", () => {
        // Pre-lineage shape: traceId is the server replay id (the direct key) and the
        // local client id rides the since-removed replayTraceId field. traceId is
        // NEVER itself a local id.
        expect(resolveReplayItemIdentity({
            traceId: "server-replay-1",
            replayTraceId: "local-1",
        })).toEqual({
            originalTraceId: null,
            traceId: "server-replay-1",
            replayTraceId: "local-1",
            persistKey: "server-replay-1",
        });
    });
    it("keyless item (no id fields): everything null, no persist key", () => {
        expect(resolveReplayItemIdentity({ error: "boom" })).toEqual({
            originalTraceId: null,
            traceId: null,
            replayTraceId: null,
            persistKey: null,
        });
    });
    it("non-object inputs resolve to the empty identity", () => {
        for (const input of [null, undefined, "x", 42, []]) {
            expect(resolveReplayItemIdentity(input)).toEqual({
                originalTraceId: null,
                traceId: null,
                replayTraceId: null,
                persistKey: null,
            });
        }
    });
    it("ignores empty-string and non-string id fields", () => {
        expect(resolveReplayItemIdentity({ originalTraceId: "", traceId: 123 })).toEqual({
            originalTraceId: null,
            traceId: null,
            replayTraceId: null,
            persistKey: null,
        });
    });
});
describe("readTraceIdAlias", () => {
    it("returns the first non-empty string among the alias keys, in order", () => {
        expect(readTraceIdAlias({ b: "second", a: "first" }, ["a", "b"])).toBe("first");
        expect(readTraceIdAlias({ a: "", b: "second" }, ["a", "b"])).toBe("second");
        expect(readTraceIdAlias({ a: 5, b: "ok" }, ["a", "b"])).toBe("ok");
        expect(readTraceIdAlias({ c: "x" }, ["a", "b"])).toBeNull();
    });
});
